// Pure renderers for the generated docs (#23, #21). Input is the registry's
// TOOLS array; output is markdown. Written defensively so it works with both
// the spike registry shape (sensitive: boolean, pageContent: boolean, no lite /
// handledBy) and the D13/D18/D21 shape (sensitive: "a".."f", pageContent:
// string[], lite, handledBy, per-action levels).

export const GENERATED_NOTE =
  "<!-- GENERATED by scripts/gen-docs.mjs from packages/protocol/src/index.ts. Do not edit; run `npm run docs:gen`. -->";

export const SENSITIVE_CATEGORIES = {
  a: "submits a form with password, card or SSN-like fields",
  b: "click matching purchase/delete/send/transfer (best-effort)",
  c: "runs arbitrary page JavaScript",
  d: "reads credentials (cookies, storage, network)",
  e: "transfers a local file",
  f: "adopts a user tab (always asks)",
};

export const LITE_VALUES = ["supported", "degraded", "unsupported"];

const toolName = (t) => String(t.name);
export const mcpName = (name) => name.replace(/\./g, "_");
const esc = (s) => String(s ?? "").replace(/\|/g, "\\|").replace(/\r?\n/g, " ");

/** @returns {{name:string, level?:string, sensitive?:string}[] | null} */
export function actionsOf(tool) {
  if (tool.actions && typeof tool.actions === "object") {
    return Object.entries(tool.actions).map(([name, a]) => ({ name, level: a?.level, sensitive: sensitiveLabel(a?.sensitive) }));
  }
  return null;
}

export function sensitiveLabel(s) {
  if (s === undefined || s === null || s === false || s === "") return "";
  if (s === true) return "yes";
  if (typeof s === "string") return s;
  if (Array.isArray(s)) return s.join(", ");
  return String(s);
}

export function pageContentLabel(pc) {
  if (Array.isArray(pc)) return pc.length ? pc.map((f) => `\`${f}\``).join(", ") : "";
  if (pc === true) return "yes";
  return "";
}

export function levelLabel(tool) {
  const acts = actionsOf(tool);
  if (acts && acts.some((a) => a.level)) return acts.map((a) => `${a.name}: ${a.level ?? tool.level ?? "?"}`).join("<br>");
  return String(tool.level ?? "?");
}

export function liteOf(tool) {
  return LITE_VALUES.includes(tool.lite) ? tool.lite : "unspecified";
}

/** Flatten a zod object's JSON Schema into parameter rows. */
export function paramRows(tool, toJSONSchema) {
  let schema = null;
  try {
    schema = toJSONSchema ? toJSONSchema(tool.params) : null;
  } catch {
    schema = null;
  }
  if (schema && schema.properties) {
    const required = new Set(schema.required ?? []);
    return Object.entries(schema.properties).map(([name, p]) => ({
      name,
      type: typeLabel(p),
      required: required.has(name),
      description: p?.description ?? "",
    }));
  }
  const shape = tool.params?.shape ?? {};
  return Object.keys(shape).map((name) => ({ name, type: "", required: false, description: shape[name]?.description ?? "" }));
}

export function typeLabel(p) {
  if (!p || typeof p !== "object") return "";
  if (Array.isArray(p.enum)) return p.enum.map((v) => JSON.stringify(v)).join(" | ");
  if (p.const !== undefined) return JSON.stringify(p.const);
  if (Array.isArray(p.anyOf)) return p.anyOf.map(typeLabel).filter(Boolean).join(" | ");
  if (p.type === "array") return `${typeLabel(p.items) || "any"}[]`;
  if (Array.isArray(p.type)) return p.type.join(" | ");
  if (p.type) return p.type;
  return "any";
}

function groupsOf(tools) {
  const order = [];
  const by = new Map();
  for (const t of tools) {
    const g = t.group ?? "other";
    if (!by.has(g)) {
      by.set(g, []);
      order.push(g);
    }
    by.get(g).push(t);
  }
  return order.map((g) => [g, by.get(g)]);
}

/** docs/tools.md */
export function renderToolsDoc(tools, toJSONSchema) {
  const out = [];
  out.push("# Tool reference", "", GENERATED_NOTE, "");
  out.push(
    "Every tool below is one registry entry (D13). On the MCP wire dots become underscores",
    "(`nav.goto` → `nav_goto`); REST is `POST /v1/call/<name>` and the CLI is `tabagent <name> --json '{…}'`.",
    "Levels are the site-policy level the tool needs (`deny < read < act < full`, D16; `none` = not site-scoped).",
    "Sensitive categories are the D18 gates: " +
      Object.entries(SENSITIVE_CATEGORIES)
        .map(([k, v]) => `**${k}** ${v}`)
        .join("; ") +
      ".",
    "Page-derived result fields are wrapped as untrusted page data at the bridge output edge (D21).",
    "",
  );
  out.push("## Summary", "", "| Tool | MCP name | Level | Sensitive | Profiles | Lite | Handled by |", "|---|---|---|---|---|---|---|");
  for (const t of tools) {
    const acts = actionsOf(t);
    const sens = acts?.some((a) => a.sensitive)
      ? acts.filter((a) => a.sensitive).map((a) => `${a.name}: ${a.sensitive}`).join("<br>")
      : sensitiveLabel(t.sensitive);
    out.push(
      `| [\`${toolName(t)}\`](#${anchor(toolName(t))}) | \`${mcpName(toolName(t))}\` | ${levelLabel(t)} | ${esc(sens) || "—"} | ${(t.profiles ?? []).join(", ") || "—"} | ${liteOf(t)} | ${t.handledBy ?? "—"} |`,
    );
  }
  out.push("");
  for (const [group, list] of groupsOf(tools)) {
    out.push(`## ${group}`, "");
    for (const t of list) {
      out.push(`### ${toolName(t)}`, "", esc(t.description), "");
      const meta = [
        `MCP name \`${mcpName(toolName(t))}\``,
        `level ${levelLabel(t).replace(/<br>/g, ", ")}`,
        `profiles ${(t.profiles ?? []).join(", ") || "—"}`,
        `lite ${liteOf(t)}`,
      ];
      const sens = sensitiveLabel(t.sensitive);
      if (sens) meta.push(`sensitive ${sens}`);
      if (t.handledBy) meta.push(`handled by ${t.handledBy}`);
      const pc = pageContentLabel(t.pageContent);
      if (pc) meta.push(`page content ${pc}`);
      out.push(meta.join(" · "), "");
      const rows = paramRows(t, toJSONSchema);
      if (rows.length) {
        out.push("| Param | Type | Required | Description |", "|---|---|---|---|");
        for (const r of rows) out.push(`| \`${r.name}\` | ${esc(r.type)} | ${r.required ? "yes" : ""} | ${esc(r.description)} |`);
      } else out.push("No parameters.");
      out.push("");
    }
  }
  return out.join("\n");
}

export function anchor(name) {
  return name.toLowerCase().replace(/[^a-z0-9 _-]/g, "").replace(/ /g, "-");
}

/** docs/lite-mode.md */
export function renderLiteDoc(tools) {
  const out = [];
  const count = (v) => tools.filter((t) => liteOf(t) === v).length;
  out.push("# Lite mode support matrix", "", GENERATED_NOTE, "");
  out.push(
    "Lite mode drives a site with content scripts only, without `chrome.debugger` (#21, D26). It is chosen",
    "per origin in the extension settings and never switches on its own; `session.info` reports each tab's mode.",
    "",
    "- **supported**: same result format as the CDP driver.",
    "- **degraded**: works, with a documented difference (for example synthetic events with `isTrusted=false`).",
    "- **unsupported**: returns `UNSUPPORTED` without touching the page.",
    "",
    `Totals: ${count("supported")} supported, ${count("degraded")} degraded, ${count("unsupported")} unsupported` +
      (count("unspecified") ? `, ${count("unspecified")} not yet declared in the registry.` : "."),
    "",
    "| Tool | Lite mode | Notes |",
    "|---|---|---|",
  );
  for (const t of tools) out.push(`| \`${toolName(t)}\` | ${liteOf(t)} | ${esc(t.liteNote ?? "")} |`);
  out.push("");
  return out.join("\n");
}
